import type { Format, Role } from '../game/types'

/**
 * The historical roster table: TEAM × SEASON × PLAYERS, as static data.
 *
 * This file is the whole database. Everything else in the game derives from it
 * — eras, nationalities, draft pools, opponents, the Champions Trophy field —
 * so adding a squad-season here is the only edit needed to put a new side in
 * the game. It is also the one file that would be replaced if these rosters
 * ever came from an API instead: nothing outside `squads.ts` reads it.
 *
 * Ratings are invented for this game. Squads list the meaningful members of
 * that season's side rather than every player who appeared.
 */

/**
 * Compact tuple: [name, role, ovr, s1, s2, s3, surnameOverride?, altRoles?]
 * Sub-rating labels come from the role. `altRoles` is a "|" list — those show
 * as a "+" on the card and let the player fill more than one slot.
 */
/**
 * A roster row comes in two shapes:
 *
 *   FULL     [name, role, ovr, s1, s2, s3, surname?, altRoles?]
 *   COMPACT  [name, role, ovr, surname?, altRoles?]
 *
 * The compact form is for squad players whose exact sub-ratings nobody would
 * claim to know — they are derived from the overall and the role instead of
 * being invented three at a time. Which shape a row is is read off whether the
 * fourth element is a number. `altRoles` is a "|" list.
 */
export type Row =
  | [string, Role, number, number, number, number, string?, string?]
  | [string, Role, number, string?, string?]

export const ROLE_FULL: Record<Role, string> = {
  WK: 'Wicketkeeper',
  BAT: 'Batter',
  AR: 'All-Rounder',
  PACE: 'Pace Bowler',
  SPIN: 'Spin Bowler',
}

/** [team, short, teamKey, season, competition, formats, players] */
export type SquadDef = [string, string, string, string, string, Format[], Row[]]

const T20 = ['T20L'] as Format[]
const INTL_MODERN = ['ODIWC', 'T20WC', 'TEST'] as Format[]
const INTL_CLASSIC = ['ODIWC', 'TEST'] as Format[]

